var EPS0=8.854187817e-12;
function capacitance(eps, A, d){ if(d<=0) return NaN; return eps*A/d; }
function energy(C, V){ return 0.5*C*V*V; }
function reactance(C, f){ if(C<=0||f<=0) return NaN; return 1/(2*Math.PI*f*C); }
var EXPORTS={capacitance:capacitance,energy:energy,reactance:reactance,EPS0:EPS0};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.CapacitorForgePure = EXPORTS; }
